let audioCtx=null;
function ensureAudio(){if(!audioCtx){try{audioCtx=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(audioCtx&&audioCtx.state==='suspended')audioCtx.resume();}
function playTone(f,d,t,v){d=d||.1;t=t||'sine';v=v||.15;if(!state.soundOn)return;try{ensureAudio();if(!audioCtx)return;var o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=t;o.frequency.value=f;g.gain.setValueAtTime(v,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+d);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+d);}catch(e){}}
const SOUNDS={hit:()=>playTone(300,.08,'square',.1),crit:()=>{playTone(600,.05,'square',.15);setTimeout(()=>playTone(900,.1,'square',.15),50);},heal:()=>{playTone(500,.1,'sine',.12);setTimeout(()=>playTone(700,.15,'sine',.12),80);},reaction:()=>{playTone(800,.08,'triangle',.18);setTimeout(()=>playTone(1200,.15,'triangle',.18),70);},kill:()=>{playTone(700,.08,'square',.15);setTimeout(()=>playTone(500,.15,'square',.15),80);},levelup:()=>[400,500,600,800].forEach((f,i)=>setTimeout(()=>playTone(f,.15,'sine',.15),i*80)),victory:()=>[500,600,700,900,1100].forEach((f,i)=>setTimeout(()=>playTone(f,.2,'sine',.15),i*100)),gacha:()=>[600,800,1000].forEach((f,i)=>setTimeout(()=>playTone(f,.15,'triangle',.15),i*60))};
function toggleSound(){state.soundOn=!state.soundOn;toast(state.soundOn?'Suara ON':'Suara OFF');}

function getCharStats(cid){const b=CHAR_DB[cid];var atk=b.atk,hp=b.maxHP,def=b.def,critRate=.05,critDmg=.5,elemDmg=0;if(b.weaponEquipped&&WEAPONS[b.weaponEquipped])atk+=Math.floor(WEAPONS[b.weaponEquipped].atk*.5);if(b.artSet&&b.artPieces>=2){var s=ARTIFACT_SETS[b.artSet];if(s.bonus2.includes('ATK'))atk=Math.floor(atk*1.18);}atk=Math.floor(atk*(1+(b.talents.normal-1)*.05));if(b.constellation>=1)atk=Math.floor(atk*1.05);return{atk:atk,hp:hp,def:def,critRate:critRate,critDmg:critDmg,elemDmg:elemDmg};}
function getActiveChar(){return CHAR_DB[state.party[state.activeIdx]];}
function getActiveEnergy(){return state.partyEnergy[state.party[state.activeIdx]]||0;}
function getResonance(){return[];}

var comboTimer=null;
function addCombo(){state.combo++;if(comboTimer)clearTimeout(comboTimer);comboTimer=setTimeout(function(){state.combo=0;renderComboUI();},3000);renderComboUI();}
function getComboMult(){if(state.combo<=2)return 1;if(state.combo<=5)return 1.15;if(state.combo<=9)return 1.3;return 1.5;}
function renderComboUI(){var el=document.getElementById('comboDisplay');if(!el)return;if(state.combo>=3){el.style.display='block';el.textContent='Combo '+state.combo+'x';}else el.style.display='none';}

function initGame(){if(!state.quests||Object.keys(state.quests).length===0)state.quests=JSON.parse(JSON.stringify(QUEST_DB));if(!state.inventory||Object.keys(state.inventory).length===0)state.inventory={food_sweet:3,potion_atk:2};state.party.forEach(function(id){if(!state.partyHP[id])state.partyHP[id]=CHAR_DB[id].maxHP;if(!state.partyEnergy[id])state.partyEnergy[id]=0;});checkEvent();renderMapTabs();spawnWave();renderAll();console.log('Game initialized');}
function checkEvent(){if(!state.eventEnd||Date.now()>state.eventEnd){state.eventActive=true;state.eventEnd=Date.now()+5*60*1000;showEventBanner();}}
function showEventBanner(){var b=document.getElementById('eventBanner');b.className='event-banner show';var u=function(){if(!state.eventActive){b.className='event-banner';return;}var l=Math.max(0,state.eventEnd-Date.now());if(l<=0){state.eventActive=false;b.className='event-banner';return;}var m=Math.floor(l/60000),s=Math.floor((l%60000)/1000);b.textContent='EVENT: Reward x2! Sisa '+m+':'+String(s).padStart(2,'0');setTimeout(u,1000);};u();}

function renderMapTabs(){var t=document.getElementById('mapTabs');t.innerHTML='';Object.values(MAPS).forEach(function(m){var un=m.unlocked||state.ar>=m.reqAR;if(!m.unlocked&&state.ar>=m.reqAR)m.unlocked=1;var e=document.createElement('div');e.className='map-tab'+(state.currentMap===m.id?' active':'')+(!un?' locked':'');e.innerHTML=m.icon+' '+m.name+(!un?' [AR'+m.reqAR+']':'');e.onclick=function(){if(!un){toast('Butuh AR '+m.reqAR);return;}state.currentMap=m.id;state.wave=1;logMsg('Pindah ke '+m.name,'log-info');renderMapTabs();spawnWave();renderAll();};t.appendChild(e);});}

function spawnWave(){state.enemies=[];var w=state.wave,m=MAPS[state.currentMap];if(w%5===0){var b=ENEMY_DB[m.boss];state.enemies.push(makeEnemy(b,w));logMsg('BOSS: '+b.name,'log-boss');}else{var pool=m.monsters.map(function(id){return ENEMY_DB[id];}).filter(function(e){return e.tier<=Math.min(4,Math.floor(w/2)+2);});var cnt=Math.min(1+Math.floor(w/2),4);for(var i=0;i<cnt;i++){var tpl=pool[Math.floor(Math.random()*pool.length)];state.enemies.push(makeEnemy(tpl,w));}logMsg('Wave '+w+'! '+cnt+' musuh.','log-info');}state.targetEnemyIdx=0;state.cooldowns={};state.shield=0;state.frozenTurns={};state.inCombat=true;state.combo=0;renderComboUI();updateEnemyGrid();updateEnemyDisplay();updatePlayerDisplay();}
function makeEnemy(tpl,w){var s=(1+(w-1)*.15)*(state.abyssMode?1.5:1);return Object.assign({},tpl,{maxHP:Math.floor(tpl.hp*s),hp:Math.floor(tpl.hp*s),atk:Math.floor(tpl.atk*s),def:Math.floor(tpl.def*s),aura:null,auraTurns:0,shield:tpl.shield||0,stunned:0});}

function useSkill(st){if(!state.inCombat)return;var ch=getActiveChar(),sk=ch.skills[st];var ck=ch.id+'_'+st,cd=state.cooldowns[ck]||0;if(cd>0){logMsg('CD '+sk.name+': '+cd,'log-info');return;}var en=getActiveEnergy();if(sk.energyCost&&en<sk.energyCost){logMsg('Energy kurang!','log-info');return;}var t=state.enemies[state.targetEnemyIdx];if(!t||t.hp<=0){var i=state.enemies.findIndex(function(e){return e.hp>0;});if(i===-1)return;state.targetEnemyIdx=i;t=state.enemies[i];}if(sk.cd>0)state.cooldowns[ck]=sk.cd;if(sk.energyCost)state.partyEnergy[ch.id]-=sk.energyCost;addCombo();if(st==='burst')SOUNDS.burst&&SOUNDS.burst();else if(st==='skill')SOUNDS.hit();else SOUNDS.hit();performAttack(ch,sk,t);if(sk.heal){var h=Math.floor(ch.maxHP*sk.heal/100);state.partyHP[ch.id]=Math.min(ch.maxHP,state.partyHP[ch.id]+h);logMsg(ch.name+' heal '+h,'log-heal');SOUNDS.heal();}if(sk.shield){state.shield+=sk.shield;logMsg('+'+sk.shield+' shield','log-info');}if(st==='normal')state.partyEnergy[ch.id]=Math.min(80,state.partyEnergy[ch.id]+8);if(st==='burst')state.counters.bursts++;renderAll();setTimeout(enemyTurn,700);}

function performAttack(ch,sk,t){var s=getCharStats(ch.id);var atk=s.atk;if(state.eventActive)atk=Math.floor(atk*1.5);var isCrit=Math.random()<(s.critRate+.05);var el=sk.element||'physical';var bd=atk*sk.dmgMult*getComboMult();var rx=null;if(el!=='physical'&&t.aura&&t.aura!==el)rx=REACTIONS[t.aura+'+'+el];if(rx)bd*=rx.mult;var dmg=Math.floor(bd*(isCrit?(1+s.critDmg):1)*(1-t.def*.02));dmg=Math.max(1,dmg);if(t.shield>0){var a=Math.min(t.shield,dmg);t.shield-=a;dmg-=a;}var wasAlive=t.hp>0;t.hp=Math.max(0,t.hp-dmg);var de=document.createElement('div');de.className='float-dmg';de.style.color=isCrit?'#ff6b35':'#fff';de.textContent=(isCrit?'*':'')+dmg;de.style.left='60%';de.style.top='30%';document.getElementById('enemyFighter').appendChild(de);setTimeout(function(){de.remove();},1000);var sp=document.getElementById('enemySprite');sp.classList.add('shake');setTimeout(function(){sp.classList.remove('shake');},300);logMsg(ch.name+' -> '+sk.name+'! '+dmg+' DMG'+(isCrit?' CRIT!':''),isCrit?'log-crit':'log-dmg');if(isCrit)state.counters.crits++;if(rx){showReaction(rx);logMsg(rx.name+'!','log-reaction');SOUNDS.reaction();state.counters.reactions++;if(rx.aoe){state.enemies.forEach(function(e,i){if(i!==state.targetEnemyIdx&&e.hp>0){var a2=Math.floor(dmg*.5);e.hp=Math.max(0,e.hp-a2);logMsg('  -> '+e.name+' +'+a2,'log-dmg');}});}if(rx.freeze){state.frozenTurns[state.targetEnemyIdx]=2;}}if(el!=='physical'){t.aura=el;t.auraTurns=3;}state.partyEnergy[ch.id]=Math.min(80,state.partyEnergy[ch.id]+(sk.energyCost?0:5));state.enemies.forEach(function(e){if(e.hp<=0&&!e._rewarded){e._rewarded=true;SOUNDS.kill();logMsg(e.name+' dikalahkan!','log-info');var mr=e.mora,xr=e.xp;if(state.eventActive){mr*=2;xr*=2;}state.mora+=mr;state.arXP+=xr;state.counters.kills++;if(wasAlive&&e.isBoss)state.storyProgress.bossKills++;if(Math.random()<.3){var l=Object.values(WEAPONS)[Math.floor(Math.random()*Object.values(WEAPONS).length)];if(state.weaponInv.indexOf(l.id)<0){state.weaponInv.push(l.id);logMsg('Loot: '+l.name,'log-loot');}}}});}

function checkARLevelUp(){var th=[0,100,300,600,1000,1500,2500,4000,6000,9000];for(var i=th.length-1;i>=0;i--){if(state.arXP>=th[i]){if(i+1>state.ar){state.ar=i+1;SOUNDS.levelup();toast('AR '+state.ar);logMsg('AR '+state.ar,'log-reaction');state.primo+=100;renderMapTabs();}break;}}}
function updateQuest(type){Object.values(state.quests).forEach(function(q){if(q.progress>=q.target)return;if(q.type===type){q.progress++;if(q.progress>=q.target){logMsg('Quest: '+q.name,'log-reaction');state.mora+=q.reward.mora;state.primo+=q.reward.primo;toast(q.name);}}else if(q.type==='wave'){q.progress=Math.max(q.progress,state.wave);if(q.progress>=q.target&&!q._done){q._done=1;logMsg('Quest: '+q.name,'log-reaction');state.mora+=q.reward.mora;state.primo+=q.reward.primo;}}});}

function useItem(iid){if(!state.inventory[iid]||state.inventory[iid]<=0)return;var ch=getActiveChar();if(iid==='food_sweet'){var h=Math.floor(ch.maxHP*.4);state.partyHP[ch.id]=Math.min(ch.maxHP,state.partyHP[ch.id]+h);logMsg('heal '+h,'log-heal');}else if(iid==='food_adeptus'){state.party.forEach(function(id){state.partyHP[id]=CHAR_DB[id].maxHP;});logMsg('Full heal!','log-heal');}else if(iid==='potion_atk'){state.buffs.atk={mult:1.3,turns:3};logMsg('ATK+30%','log-info');}else if(iid==='potion_def'){state.buffs.def={mult:1.3,turns:3};logMsg('DEF+30%','log-info');}else if(iid==='revive'){var d=state.party.find(function(id){return state.partyHP[id]<=0;});if(!d){logMsg('Tidak ada tumbang','log-info');return;}state.partyHP[d]=Math.floor(CHAR_DB[d].maxHP*.5);logMsg(CHAR_DB[d].name+' revived','log-heal');}SOUNDS.heal();state.inventory[iid]--;if(state.inventory[iid]<=0)delete state.inventory[iid];renderAll();updateInvContent();}

function enemyTurn(){if(!state.inCombat)return;if(state.godMode){Object.keys(state.cooldowns).forEach(function(k){if(state.cooldowns[k]>0)state.cooldowns[k]--;});renderAll();return;}var any=0;state.enemies.forEach(function(e,i){if(e.hp<=0)return;any=1;if(state.frozenTurns[i]>0){state.frozenTurns[i]--;logMsg(e.name+' beku','log-info');return;}var alive=state.party.filter(function(id){return state.partyHP[id]>0;});if(alive.length===0)return;var tid=alive[Math.floor(Math.random()*alive.length)],tc=CHAR_DB[tid],ts=getCharStats(tid);var dmg=Math.floor(e.atk*(1-ts.def*.015)*(.9+Math.random()*.3));if(state.buffs.def)dmg=Math.floor(dmg/state.buffs.def.mult);dmg=Math.max(1,dmg);if(state.shield>0){var a=Math.min(state.shield,dmg);state.shield-=a;dmg-=a;}if(dmg>0){state.partyHP[tid]=Math.max(0,state.partyHP[tid]-dmg);logMsg(e.name+' -> '+tc.name+' '+dmg,'log-dmg');if(state.partyHP[tid]<=0)logMsg(tc.name+' tumbang','log-boss');}});if(!any){waveCleared();return;}if(state.party.filter(function(id){return state.partyHP[id]>0;}).length===0){gameOver();return;}Object.keys(state.cooldowns).forEach(function(k){if(state.cooldowns[k]>0)state.cooldowns[k]--;});state.enemies.forEach(function(e){if(e.auraTurns>0){e.auraTurns--;if(e.auraTurns===0)e.aura=null;}});renderAll();}

function waveCleared(){if(state.domainActive){var d=DOMAINS[state.domainCurrent];state.domainWaveIdx++;if(state.domainWaveIdx>=d.waves){endDomain(true);return;}logMsg('Wave '+state.domainWaveIdx+'/'+d.waves+' clear!','log-reaction');SOUNDS.victory();setTimeout(function(){spawnDomainWave();renderAll();},1500);return;}if(state.abyssMode){endAbyss(true);return;}if(state.pvpMode){endPvP(true);return;}state.inCombat=false;state.wave++;updateQuest('wave');state.storyProgress.waveCount++;addBattlePassXP(50);var mult=state.eventActive?2:1;var bm=(50+state.wave*10)*mult,bp=30*mult;state.mora+=bm;state.primo+=bp;logMsg('Wave clear! +'+bm+' +'+bp,'log-reaction');SOUNDS.victory();state.party.forEach(function(id){if(state.partyHP[id]<=0)state.partyHP[id]=Math.floor(CHAR_DB[id].maxHP*.3);});checkAchievements();showBanner('WAVE CLEARED!','result-win');setTimeout(function(){hideBanner();spawnWave();renderAll();},1800);}
function gameOver(){if(state.domainActive){endDomain(false);return;}state.inCombat=false;logMsg('PARTY WIPE','log-boss');showBanner('GAME OVER','result-lose');setTimeout(function(){hideBanner();state.party.forEach(function(id){state.partyHP[id]=Math.floor(CHAR_DB[id].maxHP*.5);});state.wave=Math.max(1,state.wave-1);spawnWave();renderAll();},2500);}
function switchChar(i){if(i<0||i>=state.party.length)return;var id=state.party[i];if(state.partyHP[id]<=0){logMsg(CHAR_DB[id].name+' tumbang','log-info');return;}if(state.activeIdx===i)return;state.activeIdx=i;logMsg('Switch -> '+CHAR_DB[id].name,'log-info');renderAll();}

function renderAll(){renderCharBar();renderSkillBar();renderPlayerDisplay();renderEnemyDisplay();updateEnemyGrid();updateTopBar();}
function updateTopBar(){document.getElementById('mora').textContent=state.mora;document.getElementById('primo').textContent=state.primo;document.getElementById('wave').textContent=state.wave;document.getElementById('ar').textContent=state.ar;var rd=document.getElementById('resinDisp');if(rd)rd.textContent=state.resin;}
function renderCharBar(){var b=document.getElementById('charBar');b.innerHTML='';state.party.forEach(function(id,i){var c=CHAR_DB[id],hp=state.partyHP[id]||0,el=ELEMENTS[c.element];var d=document.createElement('div');d.className='char-slot'+(i===state.activeIdx?' active':'')+(hp<=0?' dead':'');d.onclick=function(){switchChar(i);};d.innerHTML='<div class="cs-key">'+(i+1)+'</div>'+(c.constellation>0?'<div class="cs-con">C'+c.constellation+'</div>':'')+'<div class="cs-sprite" style="color:'+el.color+'">'+c.sprite+'</div><div class="cs-name">'+c.name+'</div><div class="cs-el" style="color:'+el.color+'">'+el.name+'</div><div class="bar" style="height:4px;"><div class="bar-fill hp-fill" style="width:'+Math.max(0,hp/c.maxHP*100)+'%"></div></div>';b.appendChild(d);});}
function renderSkillBar(){var b=document.getElementById('skillBar');b.innerHTML='';var ch=getActiveChar();['normal','skill','burst','item','switch'].forEach(function(st){var btn=document.createElement('button');btn.className='skill-btn';if(st==='switch'){var n=(state.activeIdx+1)%state.party.length,nx=CHAR_DB[state.party[n]],el=ELEMENTS[nx.element];btn.innerHTML='<div class="sk-icon" style="color:'+el.color+'">*</div><div class="sk-name">Switch</div><div class="sk-info">'+nx.name+'</div>';btn.onclick=function(){switchChar(n);};b.appendChild(btn);return;}if(st==='item'){var items=Object.keys(state.inventory);btn.innerHTML='<div class="sk-icon">*</div><div class="sk-name">Item</div><div class="sk-info">'+items.length+'</div>';btn.onclick=function(){openModal('invModal');};b.appendChild(btn);return;}var sk=ch.skills[st],ck=ch.id+'_'+st,cd=state.cooldowns[ck]||0,en=getActiveEnergy();if(cd>0||(sk.energyCost&&en<sk.energyCost))btn.disabled=true;var el2=sk.element?ELEMENTS[sk.element]:null,ic=el2?el2.color:'#ccc';btn.innerHTML='<div class="sk-icon" style="color:'+ic+'">'+sk.icon+'</div><div class="sk-name">'+sk.name+'</div><div class="sk-info">'+(sk.energyCost?'E'+sk.energyCost:'')+(sk.cd?' C'+sk.cd:'')+'</div>'+(cd>0?'<div class="cd-overlay">'+cd+'</div>':'');btn.onclick=function(){useSkill(st);};b.appendChild(btn);});}
function renderPlayerDisplay(){var ch=getActiveChar(),hp=state.partyHP[ch.id],en=state.partyEnergy[ch.id]||0,el=ELEMENTS[ch.element];document.getElementById('playerSprite').textContent=ch.sprite;document.getElementById('playerSprite').style.color=el.color;document.getElementById('playerName').innerHTML=ch.name+' <span style="color:'+el.color+';font-size:12px;">'+el.name+'</span>';document.getElementById('playerHPText').innerHTML='HP: '+hp+' / '+ch.maxHP;document.getElementById('playerHPBar').style.width=Math.max(0,hp/ch.maxHP*100)+'%';document.getElementById('playerEnergyText').textContent='Energy: '+en+' / 80';document.getElementById('playerEnergyBar').style.width=(en/80*100)+'%';var a=document.getElementById('playerAura');a.innerHTML='';if(state.shield>0){var s=document.createElement('div');s.className='aura-icon';s.style.background='#4ecdc4';s.textContent='S';a.appendChild(s);}}
function renderEnemyDisplay(){var e=state.enemies[state.targetEnemyIdx];if(!e){document.getElementById('enemySprite').textContent='-';document.getElementById('enemyName').textContent='-';return;}var el=ELEMENTS[e.element],ph=e.isBoss?' <span class="phase-badge">BOSS</span>':'';document.getElementById('enemySprite').textContent=e.sprite;document.getElementById('enemySprite').style.color=e.hp>0?el.color:'#666';document.getElementById('enemyName').innerHTML=e.name+ph;document.getElementById('enemyHPText').textContent='HP: '+e.hp+' / '+e.maxHP+(e.shield>0?' S'+e.shield:'');document.getElementById('enemyHPBar').style.width=Math.max(0,e.hp/e.maxHP*100)+'%';var a=document.getElementById('enemyAura');a.innerHTML='';if(e.aura){var x=ELEMENTS[e.aura],d=document.createElement('div');d.className='aura-icon';d.style.background=x.color;d.textContent=x.icon;a.appendChild(d);}}
function updateEnemyGrid(){var g=document.getElementById('enemyGrid');g.innerHTML='';state.enemies.forEach(function(e,i){var el=ELEMENTS[e.element],d=document.createElement('div');d.className='enemy-mini'+(i===state.targetEnemyIdx?' target':'')+(e.hp<=0?' dead':'');d.onclick=function(){state.targetEnemyIdx=i;renderAll();};d.innerHTML='<div class="em-sprite" style="color:'+el.color+'">'+e.sprite+'</div><div style="font-size:9px;">'+e.name+'</div><div style="font-size:9px;color:#ff6b6b;">'+e.hp+'/'+e.maxHP+'</div>';g.appendChild(d);});}

function logMsg(m,c){c=c||'';var l=document.getElementById('battleLog'),p=document.createElement('p');p.className=c;p.textContent=m;l.appendChild(p);l.scrollTop=l.scrollHeight;while(l.children.length>100)l.removeChild(l.firstChild);}
function showBanner(t,c){var b=document.getElementById('resultBanner');b.textContent=t;b.className='result-banner show '+c;}
function hideBanner(){document.getElementById('resultBanner').className='result-banner';}
function toast(m){var t=document.createElement('div');t.className='toast';t.textContent=m;document.body.appendChild(t);setTimeout(function(){t.remove();},3000);}
function showReaction(r){var el=document.createElement('div');el.className='reaction-text';el.style.color=r.color;el.textContent=r.name+'!';document.getElementById('enemySide').appendChild(el);setTimeout(function(){el.remove();},900);}
function openModal(id){if(id==='invModal')updateInvContent();if(id==='charModal')renderCharModal();if(id==='talentModal')renderTalentModal();if(id==='questModal')renderQuestModal();if(id==='gachaModal')renderGachaModal();if(id==='achModal')renderAchModal();if(id==='coopModal')renderCoopModal();if(id==='bpModal')renderBPModal();if(id==='pvpModal')renderPvPModal();if(id==='craftModal')renderCraftModal();if(id==='storyModal')renderStoryModal();document.getElementById(id).classList.add('show');}
function closeModal(id){document.getElementById(id).classList.remove('show');}

var curCharTab=0;
function renderCharModal(){var t=document.getElementById('charTabs');t.innerHTML='';state.party.forEach(function(id,i){var e=document.createElement('div');e.className='tab'+(i===curCharTab?' active':'');e.textContent=CHAR_DB[id].name;e.onclick=function(){curCharTab=i;renderCharModal();};t.appendChild(e);});var cid=state.party[curCharTab],c=CHAR_DB[cid],s=getCharStats(cid),el=ELEMENTS[c.element];var wo=state.weaponInv.map(function(w){return WEAPONS[w];}).filter(function(w){return w.type===c.weapon;});document.getElementById('charContent').innerHTML='<div style="text-align:center;margin-bottom:10px;"><div style="font-size:60px;color:'+el.color+'">'+c.sprite+'</div><div style="font-size:20px;font-weight:bold;">'+c.name+'</div><div style="font-size:12px;color:#aaa;">'+c.weapon+' - C'+c.constellation+'</div></div><div class="card"><div class="c-info"><div class="c-name">Statistik</div><div class="c-desc">ATK '+s.atk+' | HP '+s.hp+' | DEF '+s.def+'</div></div></div><h3>Senjata</h3>'+wo.map(function(w){return '<div class="card rarity-'+w.rarity+' clickable" onclick="equipWeapon(\''+cid+'\',\''+w.id+'\')"><div class="c-icon">'+w.icon+'</div><div class="c-info"><div class="c-name">'+w.name+'</div><div class="c-desc">ATK +'+w.atk+'</div></div>'+(c.weaponEquipped===w.id?'<div class="c-equipped">OK</div>':'')+'</div>';}).join('')+'<h3>Artifact</h3>'+Object.values(ARTIFACT_SETS).map(function(x){var o=state.artifactInv[x.id]||0;if(o===0)return'';return '<div class="card rarity-4 clickable" onclick="equipArtSet(\''+cid+'\',\''+x.id+'\')"><div class="c-icon">'+x.icon+'</div><div class="c-info"><div class="c-name">'+x.name+'</div><div class="c-desc">'+x.bonus2+'</div><div class="c-stat">x'+o+'</div></div>'+(c.artSet===x.id?'<div class="c-equipped">OK</div>':'')+'</div>';}).join('')||'<div style="color:#666;">Belum punya</div>';}
function equipWeapon(cid,wid){CHAR_DB[cid].weaponEquipped=wid;toast(WEAPONS[wid].name);renderCharModal();renderAll();}
function equipArtSet(cid,sid){var o=state.artifactInv[sid]||0;if(o<2){toast('Butuh min 2!');return;}CHAR_DB[cid].artSet=sid;CHAR_DB[cid].artPieces=Math.min(o,4);toast(ARTIFACT_SETS[sid].name);renderCharModal();renderAll();}
function updateInvContent(){var items=Object.keys(state.inventory).map(function(iid){var it=ITEMS[iid];if(!it)return'';return '<div class="card rarity-'+it.rarity+' clickable" onclick="useItem(\''+iid+'\')"><div class="c-icon">'+it.icon+'</div><div class="c-info"><div class="c-name">'+it.name+' x'+state.inventory[iid]+'</div><div class="c-desc">'+it.desc+'</div></div><div class="c-equipped">Pakai</div></div>';}).join('')||'<div style="color:#666;">Kosong</div>';var wps=state.weaponInv.map(function(wid){var w=WEAPONS[wid];return '<div class="card rarity-'+w.rarity+'"><div class="c-icon">'+w.icon+'</div><div class="c-info"><div class="c-name">'+w.name+'</div></div></div>';}).join('');var arts=Object.keys(state.artifactInv).map(function(sid){var s=ARTIFACT_SETS[sid];return '<div class="card rarity-4"><div class="c-icon">'+s.icon+'</div><div class="c-info"><div class="c-name">'+s.name+' x'+state.artifactInv[sid]+'</div></div></div>';}).join('')||'<div style="color:#666;">Belum ada</div>';document.getElementById('invContent').innerHTML='<h3>Consumable</h3>'+items+'<h3>Weapon</h3>'+wps+'<h3>Artifact</h3>'+arts;}
function renderTalentModal(){var cid=state.party[curCharTab],c=CHAR_DB[cid],el=ELEMENTS[c.element];document.getElementById('talentContent').innerHTML='<div style="text-align:center;"><div style="font-size:50px;color:'+el.color+'">'+c.sprite+'</div><div style="font-size:18px;font-weight:bold;">'+c.name+'</div></div><h3>Talents</h3>'+['normal','skill','burst'].map(function(t){var cost=500*c.talents[t],mx=c.talents[t]>=10;return '<div class="card"><div class="c-icon">'+c.skills[t].icon+'</div><div class="c-info"><div class="c-name">'+c.skills[t].name+'</div><div class="c-desc">Lv '+c.talents[t]+' / 10</div></div><button class="btn-mini" onclick="upgradeTalent(\''+cid+'\',\''+t+'\')" '+(mx||state.mora<cost?'disabled':'')+'>'+(mx?'MAX':'$'+cost)+'</button></div>';}).join('')+'<h3>Constellation ('+c.constellation+'/6)</h3>'+[1,2,3,4,5,6].map(function(n){return '<div class="card" style="opacity:'+(n<=c.constellation?1:.4)+'"><div class="c-icon">'+(n<=c.constellation?'*':'L')+'</div><div class="c-info"><div class="c-name">C'+n+'</div></div></div>';}).join('');}
function upgradeTalent(cid,t){var c=CHAR_DB[cid],cost=500*c.talents[t];if(state.mora<cost||c.talents[t]>=10)return;state.mora-=cost;c.talents[t]++;toast('Lv'+c.talents[t]);renderTalentModal();renderAll();}
function renderQuestModal(){document.getElementById('questContent').innerHTML='<h3>Daily</h3>'+Object.values(state.quests).map(function(q){var done=q.progress>=q.target;return '<div class="card" style="opacity:'+(done?.6:1)+'"><div class="c-icon">'+(done?'OK':'Q')+'</div><div class="c-info"><div class="c-name">'+q.name+'</div><div class="c-desc">'+Math.min(q.progress,q.target)+' / '+q.target+'</div></div></div>';}).join('')+'<h3>Stats</h3><div class="card"><div class="c-info"><div class="c-name">Kills: '+state.counters.kills+'</div><div class="c-name">Reactions: '+state.counters.reactions+'</div></div></div>';}
function checkAchievements(){Object.values(ACHIEVEMENTS).forEach(function(a){if(state.achievements.indexOf(a.id)>=0)return;if(a.check()){state.achievements.push(a.id);state.mora+=a.reward.mora;state.primo+=a.reward.primo;toast(a.name);}});}
function renderAchModal(){document.getElementById('achContent').innerHTML=Object.values(ACHIEVEMENTS).map(function(a){var u=state.achievements.indexOf(a.id)>=0;return '<div class="card" style="opacity:'+(u?1:.5)+'"><div class="c-icon">'+(u?'*':'L')+'</div><div class="c-info"><div class="c-name">'+a.name+'</div><div class="c-desc">'+a.desc+'</div></div></div>';}).join('');}
function renderGachaModal(){document.getElementById('gachaResult').innerHTML='<p style="text-align:center;">Primo: '+state.primo+'</p><p style="text-align:center;font-size:11px;color:#aaa;">Pity: '+state.gachaPity+'/90</p><button class="close-btn" style="background:#ffd93d;color:#000;width:100%;" onclick="doGacha(1)">x1 (160)</button><button class="close-btn" style="background:#a29bfe;color:#000;width:100%;" onclick="doGacha(10)">x10 (1600)</button>';}
function doGacha(n){var cost=n*160;if(state.primo<cost){toast('Primo kurang!');return;}state.primo-=cost;SOUNDS.gacha();var all=Object.values(CHAR_DB),res=[];for(var i=0;i<n;i++){state.gachaPity++;var p,is5=false;if(state.gachaPity>=90||Math.random()<.05){p=all[Math.floor(Math.random()*all.length)];is5=true;state.gachaPity=0;}else p=all[Math.floor(Math.random()*all.length)];var isNew=state.ownedChars.indexOf(p.id)<0;if(isNew){state.ownedChars.push(p.id);state.partyHP[p.id]=p.maxHP;state.partyEnergy[p.id]=0;}else{if(p.constellation<6)p.constellation++;else state.mora+=500;}res.push({char:p,isNew:isNew,is5:is5});}var c=document.getElementById('gachaResult');c.innerHTML='<h3>Hasil</h3>';res.forEach(function(r){var el=ELEMENTS[r.char.element],d=document.createElement('div');d.className='gacha-card';d.style.background=r.is5?'linear-gradient(135deg,#ffd93d,#ff6b35)':'linear-gradient(135deg,#a29bfe,#4ecdc4)';d.innerHTML='<div style="font-size:40px;">'+r.char.sprite+'</div><div style="font-size:16px;font-weight:bold;color:#000;">'+r.char.name+'</div><div style="font-size:11px;color:#000;">'+(r.isNew?'NEW!':'+C')+'</div>';c.appendChild(d);});var b=document.createElement('button');b.className='close-btn';b.textContent='Kembali';b.onclick=renderGachaModal;c.appendChild(b);checkAchievements();renderAll();}
function renderCoopModal(){document.getElementById('coopContent').innerHTML='<h3>Ally</h3>'+COOP_ALLIES.map(function(a){var ac=state.coopAllies.indexOf(a.id)>=0,el=ELEMENTS[a.element];return '<div class="card clickable" onclick="var i=state.coopAllies.indexOf(\''+a.id+'\');if(i>=0)state.coopAllies.splice(i,1);else state.coopAllies.push(\''+a.id+'\');renderCoopModal();"><div class="c-icon" style="color:'+el.color+'">*</div><div class="c-info"><div class="c-name">'+a.name+'</div></div>'+(ac?'<div class="c-equipped">OK</div>':'')+'</div>';}).join('');}
function toggleAbyss(){document.getElementById('abyssPanel').classList.toggle('show');}
function startAbyss(){if(state.abyssMode)return;state.abyssMode=true;state.abyssTime=state.abyssTotalTime;state.abyssFloor++;logMsg('Abyss F'+state.abyssFloor,'log-reaction');spawnWave();renderAll();if(state.abyssTimer)clearInterval(state.abyssTimer);state.abyssTimer=setInterval(function(){state.abyssTime--;var t=state.abyssTime,m=Math.floor(t/60),s=t%60;document.getElementById('abyssTimer').textContent=m+':'+String(s).padStart(2,'0');if(t<=0)endAbyss(false);},1000);document.getElementById('abyssStartBtn').textContent='...';document.getElementById('abyssStartBtn').disabled=true;}
function endAbyss(win){clearInterval(state.abyssTimer);state.abyssTimer=null;state.abyssMode=false;document.getElementById('abyssStartBtn').textContent='Mulai Abyss';document.getElementById('abyssStartBtn').disabled=false;if(win){state.mora+=500*state.abyssFloor;state.primo+=100;showBanner('ABYSS CLEAR!','result-win');SOUNDS.victory();}else{showBanner('ABYSS GAGAL','result-lose');state.abyssFloor=Math.max(0,state.abyssFloor-1);}setTimeout(function(){hideBanner();state.party.forEach(function(id){state.partyHP[id]=CHAR_DB[id].maxHP;});state.wave=1;spawnWave();renderAll();},2500);}
function renderPvPModal(){var rank=PVP_RANKS[0];PVP_RANKS.forEach(function(r){if(state.pvpPoints>=r.min)rank=r;});document.getElementById('pvpContent').innerHTML='<div style="text-align:center;"><div style="font-size:40px;">'+rank.icon+'</div><div>'+state.pvpPoints+' Points</div><div style="font-size:12px;">W: '+state.pvpWins+' | L: '+state.pvpLosses+'</div></div><div style="text-align:center;margin-top:10px;"><button class="btn-mini" onclick="startPvP()">Cari Lawan</button></div>';}
function startPvP(){var pool=Object.values(CHAR_DB),ec=pool[Math.floor(Math.random()*pool.length)];var s=getCharStats(ec.id),sc=.8+state.pvpPoints/5000;var b={id:'pvp',name:'AI: '+ec.name,sprite:ec.sprite,element:ec.element,hp:Math.floor(ec.maxHP*sc),maxHP:Math.floor(ec.maxHP*sc),atk:Math.floor(s.atk*sc),def:ec.def,xp:200,mora:300,aura:null,auraTurns:0,shield:0};state.enemies=[b];state.wave=1;state.targetEnemyIdx=0;state.cooldowns={};state.inCombat=true;state.pvpMode=true;logMsg('PvP vs '+b.name,'log-boss');closeModal('pvpModal');renderAll();}
function endPvP(win){state.pvpMode=false;if(win){state.pvpWins++;state.pvpPoints+=50;state.mora+=500;state.primo+=50;toast('PvP Win!');}else{state.pvpLosses++;state.pvpPoints=Math.max(0,state.pvpPoints-20);}setTimeout(function(){state.party.forEach(function(id){state.partyHP[id]=Math.floor(CHAR_DB[id].maxHP*.7);});state.wave=1;spawnWave();renderAll();},2000);}
function renderCraftModal(){document.getElementById('craftContent').innerHTML='<h3>Crafting</h3><p style="text-align:center;color:#aaa;">Coming soon</p>';}
function renderStoryModal(){document.getElementById('storyContent').innerHTML='<h3>Story</h3><p style="text-align:center;color:#aaa;">Coming soon</p>';}
function addBattlePassXP(n){BATTLE_PASS.xp+=n;while(BATTLE_PASS.xp>=BATTLE_PASS.xpPerLevel&&BATTLE_PASS.level<50){BATTLE_PASS.xp-=BATTLE_PASS.xpPerLevel;BATTLE_PASS.level++;toast('BP Lv'+BATTLE_PASS.level);}}
function renderBPModal(){document.getElementById('bpContent').innerHTML='<div style="text-align:center;"><div style="font-size:30px;">Level '+BATTLE_PASS.level+' / 50</div><div class="bar" style="height:14px;margin:8px 0;"><div class="bar-fill energy-fill" style="width:'+(BATTLE_PASS.xp/BATTLE_PASS.xpPerLevel*100)+'%"></div></div></div>';}

function openDomains(){var modal=document.createElement('div');modal.className='modal show';modal.id='domainModal';modal.innerHTML='<div class="modal-content"><h2>Domains</h2><div style="text-align:center;margin-bottom:12px;">Resin: <b>'+state.resin+'/'+state.resinMax+'</b> <button class="btn-mini" onclick="if(state.primo>=50){state.primo-=50;state.resin=Math.min(160,state.resin+60);toast(\'+60 Resin!\');document.getElementById(\'domainModal\').remove();openDomains();renderAll();}">+60 (50)</button></div><div>'+Object.values(DOMAINS).map(function(d){var unlocked=state.ar>=d.reqAR;var stars=state.domainStars[d.id]||0;var canEnter=unlocked&&state.resin>=d.resin&&!state.domainActive;return '<div class="card" style="background:'+d.bg+';display:block;padding:10px;"><div style="font-size:15px;font-weight:bold;">'+d.icon+' '+d.name+'</div><div style="font-size:11px;color:#ccc;">'+d.desc+'</div><div style="font-size:11px;color:#aaa;">AR '+d.reqAR+' - '+d.resin+' Resin</div>'+(!unlocked?'<div style="color:#888;font-size:11px;">AR'+d.reqAR+'</div>':state.resin<d.resin?'<div style="color:#ff4444;font-size:11px;">Resin kurang</div>':canEnter?'<button class="btn-mini" style="background:linear-gradient(90deg,#ffd93d,#ff6b35);color:#000;" onclick="document.getElementById(\'domainModal\').remove();enterDomain(\''+d.id+'\')">Masuk</button>':'')+'</div>';}).join('')+'</div><button class="close-btn" onclick="document.getElementById(\'domainModal\').remove()">Tutup</button></div>';document.body.appendChild(modal);}
function enterDomain(domainId){var d=DOMAINS[domainId];if(!d||state.resin<d.resin||state.domainActive)return;state.resin-=d.resin;state.domainActive=true;state.domainCurrent=domainId;state.domainWaveIdx=0;document.querySelector('.game').style.background=d.bg;logMsg('Memasuki '+d.name,'log-reaction');toast(d.name);spawnDomainWave();if(d.timer>0){state.domainTimeLeft=d.timer;if(state.domainTimer)clearInterval(state.domainTimer);state.domainTimer=setInterval(function(){state.domainTimeLeft--;var el=document.getElementById('domainTimerHUD');if(el)el.textContent='T '+Math.floor(state.domainTimeLeft/60)+':'+String(state.domainTimeLeft%60).padStart(2,'0');if(state.domainTimeLeft<=0)endDomain(false);},1000);}showDomainHUD();renderAll();}
function showDomainHUD(){var hud=document.getElementById('domainHUD');if(!hud){hud=document.createElement('div');hud.id='domainHUD';hud.style.cssText='position:fixed;top:10px;left:50%;transform:translateX(-50%);background:rgba(0,0,0,0.9);padding:8px 16px;border-radius:20px;border:2px solid #ffd93d;z-index:90;font-weight:bold;display:flex;gap:15px;align-items:center;font-size:13px;';document.body.appendChild(hud);}var d=DOMAINS[state.domainCurrent];hud.innerHTML='<span style="color:#ffd93d;">'+d.icon+' '+d.name+'</span><span style="color:#4ecdc4;" id="domainTimerHUD">T '+Math.floor((state.domainTimeLeft||0)/60)+':'+String((state.domainTimeLeft||0)%60).padStart(2,'0')+'</span><span style="color:#ff6b35;" id="domainWaveHUD">W '+(state.domainWaveIdx+1)+'/'+d.waves+'</span><button class="btn-mini" style="background:#8b0000;" onclick="exitDomain()">X</button>';}
function spawnDomainWave(){var d=DOMAINS[state.domainCurrent];var w=state.domainWaveIdx;state.enemies=[];if(d.id==='boss_domain'){if(d.enemies[w])state.enemies.push(makeEnemy(ENEMY_DB[d.enemies[w]],10));}else{if(w===d.waves-1)state.enemies.push(makeEnemy(ENEMY_DB[d.enemies[d.enemies.length-1]],10));else d.enemies.forEach(function(eid){state.enemies.push(makeEnemy(ENEMY_DB[eid],8+w*3));});}state.targetEnemyIdx=0;state.cooldowns={};state.shield=0;state.frozenTurns={};state.inCombat=true;state.combo=0;var wh=document.getElementById('domainWaveHUD');if(wh)wh.textContent='W '+(state.domainWaveIdx+1)+'/'+d.waves;updateEnemyGrid();updateEnemyDisplay();updatePlayerDisplay();renderAll();}
function endDomain(win){var d=DOMAINS[state.domainCurrent];if(state.domainTimer)clearInterval(state.domainTimer);state.domainTimer=null;state.domainActive=false;state.inCombat=false;var stars=0;if(win){stars=1;if(state.party.every(function(id){return state.partyHP[id]>0;}))stars=2;if(d.timer>0&&state.domainTimeLeft>d.timer*0.3)stars=3;var mult=stars===3?1.5:stars===2?1.25:1;var rm=Math.floor(d.reward.mora*mult);var rp=Math.floor(d.reward.primo*mult);state.mora+=rm;state.primo+=rp;var artTxt='';if(d.reward.artifact){state.artifactInv[d.reward.artifact]=(state.artifactInv[d.reward.artifact]||0)+1;artTxt='Artifact: '+ARTIFACT_SETS[d.reward.artifact].name;}var oldStars=state.domainStars[d.id]||0;if(stars>oldStars)state.domainStars[d.id]=stars;var fcTxt='';if(!state.domainFirstClear[d.id]&&d.firstClear){state.domainFirstClear[d.id]=true;state.mora+=d.firstClear.mora;state.primo+=d.firstClear.primo;fcTxt='FIRST CLEAR!';}SOUNDS.victory();var modal=document.createElement('div');modal.className='modal show';modal.id='domainResultModal';modal.style.zIndex='200';modal.innerHTML='<div class="modal-content" style="text-align:center;max-width:450px;"><div style="font-size:60px;">*</div><h2>DOMAIN CLEAR!</h2><div style="font-size:50px;margin:10px 0;color:#ffd93d;">'+'*'.repeat(stars)+'o'.repeat(3-stars)+'</div><div style="font-size:14px;color:#aaa;">'+d.icon+' '+d.name+'</div><div class="card" style="margin-top:10px;"><div class="c-info" style="text-align:left;"><div class="c-name">Reward</div><div class="c-stat">+'+rm+' Mora</div><div class="c-stat">+'+rp+' Primo</div><div style="color:#ffd93d;">'+artTxt+'</div><div style="color:#ffd93d;font-weight:bold;">'+fcTxt+'</div></div></div></div>';document.body.appendChild(modal);}else{var modal2=document.createElement('div');modal2.className='modal show';modal2.id='domainResultModal';modal2.style.zIndex='200';modal2.innerHTML='<div class="modal-content" style="text-align:center;max-width:450px;"><div style="font-size:60px;">X</div><h2>DOMAIN FAILED</h2><div style="font-size:14px;color:#aaa;">'+d.icon+' '+d.name+'</div></div>';document.body.appendChild(modal2);}document.querySelector('.game').style.background='linear-gradient(180deg,#1a1a2e,#0f0f1e)';var hud=document.getElementById('domainHUD');if(hud)hud.remove();checkAchievements();setTimeout(function(){var rm2=document.getElementById('domainResultModal');if(rm2)rm2.remove();state.wave=1;state.party.forEach(function(id){state.partyHP[id]=CHAR_DB[id].maxHP;});spawnWave();renderAll();},4500);}
function exitDomain(){if(!state.domainActive)return;if(!confirm('Keluar dari domain?'))return;if(state.domainTimer)clearInterval(state.domainTimer);state.domainActive=false;state.inCombat=false;var hud=document.getElementById('domainHUD');if(hud)hud.remove();document.querySelector('.game').style.background='linear-gradient(180deg,#1a1a2e,#0f0f1e)';state.wave=1;state.party.forEach(function(id){state.partyHP[id]=CHAR_DB[id].maxHP;});spawnWave();renderAll();}

function saveGame(){try{localStorage.setItem('elem_chron_v5',JSON.stringify({state:state,charDB:Object.fromEntries(Object.entries(CHAR_DB).map(function(e){return[e[0],{weaponEquipped:e[1].weaponEquipped,artSet:e[1].artSet,artPieces:e[1].artPieces,constellation:e[1].constellation,talents:e[1].talents}];}))}));toast('Tersimpan!');}catch(e){toast('Gagal save');}}
function loadGame(){try{var d=localStorage.getItem('elem_chron_v5');if(!d){toast('Tidak ada save');return;}var p=JSON.parse(d);Object.assign(state,p.state);if(p.charDB)Object.entries(p.charDB).forEach(function(e){if(CHAR_DB[e[0]])Object.assign(CHAR_DB[e[0]],e[1]);});document.getElementById('battleLog').innerHTML='';logMsg('Dimuat','log-info');renderMapTabs();spawnWave();renderAll();}catch(e){toast('Gagal load');}}

function toggleAdminPanel(){state.adminMode=!state.adminMode;var p=document.getElementById('adminPanel');if(state.adminMode){if(!p){createAdminPanel();p=document.getElementById('adminPanel');}p.style.display='block';}else if(p){p.style.display='none';}toast(state.adminMode?'Admin ON':'Admin OFF');}
function createAdminPanel(){var p=document.createElement('div');p.id='adminPanel';p.style.cssText='position:fixed;top:60px;left:50%;transform:translateX(-50%);width:95%;max-width:500px;max-height:70vh;overflow-y:auto;background:linear-gradient(180deg,#2a0a0a,#1a0505);border:3px solid #ff4444;border-radius:12px;padding:15px;z-index:9999;box-shadow:0 0 50px rgba(255,68,68,0.7);color:#fff;';p.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;"><h2 style="color:#ff4444;margin:0;font-size:18px;">ADMIN PANEL</h2><button onclick="toggleAdminPanel()" style="background:#ff4444;color:#fff;border:none;padding:5px 12px;border-radius:5px;cursor:pointer;font-weight:bold;">X</button></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;"><button onclick="adminAddMora()" style="background:#ffd93d;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">+10K Mora</button><button onclick="adminAddPrimo()" style="background:#a29bfe;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">+10K Primo</button><button onclick="adminAddResin()" style="background:#4ecdc4;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">+999 Resin</button><button onclick="adminSetAR()" style="background:#ff6b35;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">Set AR 15</button><button onclick="adminHealAll()" style="background:#6bcf7f;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">Heal All</button><button onclick="adminEnergyAll()" style="background:#ffd93d;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">Energy Full</button><button onclick="adminMaxTalents()" style="background:#ff8c42;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">Max Talents</button><button onclick="adminC6All()" style="background:#a29bfe;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">C6 All</button><button onclick="adminUnlockChars()" style="background:#ffd93d;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">All Chars</button><button onclick="adminUnlockAll()" style="background:#ff6b35;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">Unlock All</button><button onclick="adminKillEnemies()" style="background:#ff4444;color:#fff;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">Kill All</button><button onclick="adminNextWave()" style="background:#ff8c42;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">Next Wave</button><button onclick="adminGodMode()" id="godBtn" style="background:#2a2a5a;color:#fff;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">God Mode</button><button onclick="adminOneHitKill()" id="ohkBtn" style="background:#2a2a5a;color:#fff;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">One Hit</button><button onclick="adminAddAllItems()" style="background:#4ecdc4;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">Items x99</button><button onclick="adminAddWeapons()" style="background:#a29bfe;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">Weapons</button><button onclick="adminAddArtifacts()" style="background:#ffd93d;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">Artifacts</button><button onclick="adminFinishDomains()" style="background:#4ecdc4;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">Clear Domains</button><button onclick="adminResetWave()" style="background:#a29bfe;color:#000;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">Reset Wave</button><button onclick="adminResetAll()" style="background:#8b0000;color:#fff;border:none;padding:8px;border-radius:5px;cursor:pointer;font-weight:bold;">RESET</button></div>';document.body.appendChild(p);}
function adminAddMora(){state.mora+=10000;toast('+10K Mora');renderAll();}
function adminAddPrimo(){state.primo+=10000;toast('+10K Primo');renderAll();}
function adminAddResin(){state.resin=999;state.resinMax=999;toast('+999 Resin');renderAll();}
function adminSetAR(){state.ar=15;state.arXP=25000;toast('AR 15');renderMapTabs();renderAll();}
function adminHealAll(){state.party.forEach(function(id){state.partyHP[id]=CHAR_DB[id].maxHP;});toast('Heal!');renderAll();}
function adminEnergyAll(){state.party.forEach(function(id){state.partyEnergy[id]=80;});toast('Energy!');renderAll();}
function adminMaxTalents(){state.party.forEach(function(id){CHAR_DB[id].talents.normal=10;CHAR_DB[id].talents.skill=10;CHAR_DB[id].talents.burst=10;});toast('Max!');renderAll();}
function adminC6All(){state.party.forEach(function(id){CHAR_DB[id].constellation=6;});toast('C6!');renderAll();}
function adminUnlockChars(){Object.keys(CHAR_DB).forEach(function(id){if(state.ownedChars.indexOf(id)<0){state.ownedChars.push(id);state.partyHP[id]=CHAR_DB[id].maxHP;state.partyEnergy[id]=0;}});toast('All Chars!');renderAll();}
function adminUnlockAll(){Object.values(MAPS).forEach(function(m){m.unlocked=1;});state.ar=15;state.resin=999;toast('Unlocked!');renderMapTabs();renderAll();}
function adminKillEnemies(){state.enemies.forEach(function(e){e.hp=0;if(!e._rewarded){e._rewarded=true;state.mora+=e.mora;state.arXP+=e.xp;state.counters.kills++;}});toast('Kill All!');setTimeout(waveCleared,500);renderAll();}
function adminNextWave(){state.enemies.forEach(function(e){e.hp=0;});toast('Next!');setTimeout(waveCleared,300);}
function adminGodMode(){state.godMode=!state.godMode;toast(state.godMode?'God ON':'God OFF');var b=document.getElementById('godBtn');if(b)b.style.background=state.godMode?'#4ecdc4':'#2a2a5a';}
function adminOneHitKill(){state.oneHitKill=!state.oneHitKill;toast(state.oneHitKill?'OHK ON':'OHK OFF');var b=document.getElementById('ohkBtn');if(b)b.style.background=state.oneHitKill?'#ff4444':'#2a2a5a';}
function adminAddAllItems(){Object.keys(ITEMS).forEach(function(id){state.inventory[id]=99;});toast('Items!');}
function adminAddWeapons(){Object.keys(WEAPONS).forEach(function(id){if(state.weaponInv.indexOf(id)<0)state.weaponInv.push(id);});toast('Weapons!');}
function adminAddArtifacts(){Object.keys(ARTIFACT_SETS).forEach(function(id){state.artifactInv[id]=10;});toast('Artifacts!');}
function adminFinishDomains(){Object.keys(DOMAINS).forEach(function(id){state.domainFirstClear[id]=true;state.domainStars[id]=3;});toast('Domains Clear!');}
function adminResetWave(){state.wave=1;spawnWave();toast('Wave 1!');}
function adminResetAll(){if(!confirm('Reset semua?'))return;localStorage.clear();location.reload();}
var _origEnemyTurnA=enemyTurn;
enemyTurn=function(){if(state.godMode){Object.keys(state.cooldowns).forEach(function(k){if(state.cooldowns[k]>0)state.cooldowns[k]--;});renderAll();return;}_origEnemyTurnA.call(this);};
var _origPerformAttackA=performAttack;
performAttack=function(char,skill,target){if(state.oneHitKill){var saved=skill.dmgMult;skill.dmgMult=99999;_origPerformAttackA.call(this,char,skill,target);skill.dmgMult=saved;}else{_origPerformAttackA.call(this,char,skill,target);}};

var MENU_DATA=[{section:'UTAMA',items:[{label:'Karakter',emoji:'👥',action:"openModal('charModal')"},{label:'Inventory',emoji:'🎒',action:"openModal('invModal')"},{label:'Talent',emoji:'📚',action:"openModal('talentModal')"}]},{section:'PROGRESI',items:[{label:'Quest',emoji:'📜',action:"openModal('questModal')"},{label:'Achievement',emoji:'🏆',action:"openModal('achModal')"},{label:'Battle Pass',emoji:'🎫',action:"openModal('bpModal')"},{label:'Domain',emoji:'🏰',action:"openDomains()"},{label:'Spiral Abyss',emoji:'🌀',action:"toggleAbyss()"}]},{section:'PERTEMPURAN',items:[{label:'PvP',emoji:'⚔️',action:"openModal('pvpModal')"},{label:'Co-op',emoji:'🤝',action:"openModal('coopModal')"},{label:'Story',emoji:'📖',action:"openModal('storyModal')"}]},{section:'GACHA',items:[{label:'Character',emoji:'🎁',action:"openModal('gachaModal')"}]},{section:'SISTEM',items:[{label:'Crafting',emoji:'⚒️',action:"openModal('craftModal')"},{label:'Save',emoji:'💾',action:"saveGame()"},{label:'Load',emoji:'📂',action:"loadGame()"},{label:'Admin',emoji:'🛡️',action:"toggleAdminPanel()"},{label:'Sound',emoji:'🔊',action:"toggleSound()"}]}];
function createSidebar(){if(document.getElementById('sidebarToggle'))return;var t=document.createElement('button');t.id='sidebarToggle';t.className='sidebar-toggle';t.textContent='☰';t.onclick=toggleSidebar;document.body.appendChild(t);var sb=document.createElement('div');sb.id='sidebar';sb.className='sidebar';var html='<div class="sb-header"><h3>MENU</h3></div>';MENU_DATA.forEach(function(g){html+='<div class="sb-section"><div class="sb-section-title">'+g.section+'</div>';g.items.forEach(function(it){html+='<button class="sb-btn" onclick="'+it.action+';closeSidebar();"><span class="sb-emoji">'+it.emoji+'</span><span class="sb-label">'+it.label+'</span></button>';});html+='</div>';});sb.innerHTML=html;document.body.appendChild(sb);updateTopbarText();console.log('Sidebar created!');}
function updateTopbarText(){var bg=document.getElementById('topbarBtns');if(!bg)return;bg.innerHTML='';var btns=[{l:'Karakter',c:'',a:"openModal('charModal')"},{l:'Inventory',c:'',a:"openModal('invModal')"},{l:'Gacha',c:'primary',a:"openModal('gachaModal')"},{l:'Domain',c:'success',a:"openDomains()"},{l:'Abyss',c:'info',a:"toggleAbyss()"},{l:'Save',c:'',a:"saveGame()"},{l:'Admin',c:'danger',a:"toggleAdminPanel()"}];btns.forEach(function(b){var btn=document.createElement('button');btn.className='btn-text '+b.c;btn.textContent=b.l;btn.onclick=new Function(b.a);bg.appendChild(btn);});console.log('Topbar updated');}
function toggleSidebar(){var sb=document.getElementById('sidebar');var t=document.getElementById('sidebarToggle');if(!sb||!t)return;sb.classList.toggle('open');t.classList.toggle('open');t.textContent=sb.classList.contains('open')?'X':'☰';}
function closeSidebar(){var sb=document.getElementById('sidebar');var t=document.getElementById('sidebarToggle');if(sb)sb.classList.remove('open');if(t){t.classList.remove('open');t.textContent='☰';}}
window.toggleSidebar=toggleSidebar;window.closeSidebar=closeSidebar;

document.addEventListener('keydown',function(e){if(e.ctrlKey&&e.shiftKey&&(e.key==='A'||e.key==='a')){e.preventDefault();toggleAdminPanel();}else if(e.key>='1'&&e.key<='4')switchChar(parseInt(e.key)-1);else if(e.key==='q'||e.key==='Q')useSkill('normal');else if(e.key==='e'||e.key==='E')useSkill('skill');else if(e.key==='r'||e.key==='R')useSkill('burst');else if(e.key==='i'||e.key==='I')openModal('invModal');});

// INIT
function startGame(){initGame();createSidebar();setInterval(checkAchievements,5000);setInterval(function(){if(!state.eventActive&&(!state.eventEnd||Date.now()>state.eventEnd))checkEvent();},60000);setInterval(function(){if(state.resin<state.resinMax){state.resin=Math.min(state.resinMax,state.resin+1);var rd=document.getElementById('resinDisp');if(rd)rd.textContent=state.resin;}},480000);logMsg('ELEMENTAL CHRONICLES - ULTIMATE!','log-reaction');logMsg('Kontrol: [1-4] Switch | [Q/E/R] Skill | [I] Inv','log-info');console.log('✅ Game started!');}

if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',startGame);}else{startGame();}